using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using MyFundex.BuildingBlocks.Abstractions;using MyFundex.BuildingBlocks.Domain;using MyFundex.BuildingBlocks.Persistence;
namespace MyFundex.Portfolio;
public sealed class Position:EntityBase{public Guid PositionId{get;set;}public long FundedAccountInternalId{get;set;}public string InstrumentToken{get;set;}="";public string Symbol{get;set;}="";public decimal Quantity{get;set;}public decimal AverageCost{get;set;}public decimal RealizedPnl{get;set;}public decimal UnrealizedPnl{get;set;}public string Status{get;set;}="Open";public DateTimeOffset OpenedAt{get;set;}public DateTimeOffset? ClosedAt{get;set;}}
public sealed class PositionLot:EntityBase{public Guid LotId{get;set;}public long PositionInternalId{get;set;}public long ExecutionInternalId{get;set;}public decimal OriginalQuantity{get;set;}public decimal RemainingQuantity{get;set;}public decimal PurchasePrice{get;set;}public DateTimeOffset AcquiredAt{get;set;}public DateTimeOffset? MustExitBy{get;set;}}
public sealed class PortfolioDbContext(DbContextOptions<PortfolioDbContext>o,ICurrentActor a):AuditableDbContext(o,a){public DbSet<Position>Positions=>Set<Position>();public DbSet<PositionLot>Lots=>Set<PositionLot>();protected override void OnModelCreating(ModelBuilder m){m.HasDefaultSchema("portfolio");ConfigureEntity(m.Entity<Position>());ConfigureEntity(m.Entity<PositionLot>());m.Entity<Position>().HasIndex(x=>x.PositionId).IsUnique();m.Entity<Position>().HasIndex(x=>new{x.FundedAccountInternalId,x.InstrumentToken}).HasFilter("is_deleted=false AND status='Open'");}}
public static class PortfolioModule{public static IServiceCollection AddPortfolioModule(this IServiceCollection s,string cs){s.AddDbContext<PortfolioDbContext>(o=>o.UseNpgsql(cs));return s;}}
